/**
 * Registers the production service worker generated by vite-plugin-pwa (Workbox).
 * Only activates in browser environments that support service workers.
 */
export function registerPwaServiceWorker(): void {
  if (typeof window !== 'undefined' && 'serviceWorker' in navigator) {
    window.addEventListener('load', () => {
      // In Vite production builds, vite-plugin-pwa outputs sw.js to the root
      const swUrl = '/sw.js';
      navigator.serviceWorker
        .register(swUrl, { scope: '/' })
        .then((registration) => {
          // Periodically check for service worker updates (e.g. every hour)
          setInterval(() => {
            registration.update().catch((err) => {
              console.warn('Periodic service worker update check failed:', err);
            });
          }, 60 * 60 * 1000);
        })
        .catch((error) => {
          // Service worker registration will fail on non-HTTPS in production, which is expected
          console.warn('Service worker registration could not be completed:', error);
        });
    });
  }
}
